from typing import List

class SolutionMemoized:
    def change(self, amount: int, coins: List[int]) -> int:
        memo = {}

        def dfs(i: int, rem: int) -> int:
            if rem == 0:
                return 1
            if rem < 0 or i == len(coins):
                return 0
            if (i, rem) not in memo:
                memo[(i, rem)] = dfs(i, rem - coins[i]) + dfs(i + 1, rem)
            return memo[(i, rem)]

        return dfs(0, amount)

