from typing import List

class Solution:
    def change(self, amount: int, coins: List[int]) -> int:
        dp = [0] * (amount + 1)
        dp[0] = 1
        for coin in coins:
            # Forward pass allows reusing the same coin.
            for total in range(coin, amount + 1):
                dp[total] += dp[total - coin]
        return dp[amount]

